/bin/bash -lc "/opt/conda/bin/pvpython - <<'PY'
from paraview.simple import *
import glob
r=XMLImageDataReader(FileName=sorted(glob.glob('/workspace/Ionization/*.vti')))
print('reader',r)
for a in ['FileName','TimeArray','PointArrayStatus','CellArrayStatus']:
 try: print(a,getattr(r,a))
 except: pass
UpdatePipeline(proxy=r)
print(r.GetDataInformation().GetPointDataInformation().GetArrayInformation(0).GetName())
for cls in [TTKPersistenceDiagram,TTKTopologicalSimplificationByPersistence,TTKContourTree]:
 print('\\n',cls)
 try:
  x=cls(Input=r)
  print(x.ListProperties())
  for p in x.ListProperties():
   if any(s in p.lower() for s in ['scalar','persistence','simplif','offset','tree','input']):
    try: print(p, getattr(x,p))
    except Exception as e:print(p,e)
 except Exception as e:print(e)
PY"

